"use client";

import { cn } from "@/lib/utils";
import {
    Eye,
    Ear,
    Hand,
    Wind,
    Sparkles,
    ArrowRight,
    Brain,
} from "lucide-react";

// --- Types ---

export interface PhenomenologyData {
    reality_comparison?: string;
    vividness?: string;
    sensory_modalities?: string[];
    emotional_progression?: string[];
    altered_cognition?: string[];
}

// --- Config ---

// Reality comparison scale — from NoeticMap
const REALITY_LEVELS = [
    { value: "less_real", label: "Less Real", position: 0, color: "bg-slate-300" },
    { value: "equally_real", label: "Equally Real", position: 33, color: "bg-blue-400" },
    { value: "more_real", label: "More Real", position: 66, color: "bg-blue-500" },
    { value: "most_real", label: "Most Real Ever", position: 100, color: "bg-blue-600" },
];

const VIVIDNESS_LEVELS = [
    { value: "faint", label: "Faint", color: "bg-slate-300" },
    { value: "normal", label: "Normal", color: "bg-blue-300" },
    { value: "vivid", label: "Vivid", color: "bg-blue-500" },
    { value: "hyper_vivid", label: "Hyper-Vivid", color: "bg-indigo-600" },
];

// Sensory icons
const SENSORY_ICONS: Record<string, { icon: typeof Eye; label: string }> = {
    visual: { icon: Eye, label: "Visual" },
    auditory: { icon: Ear, label: "Auditory" },
    tactile: { icon: Hand, label: "Tactile" },
    olfactory: { icon: Wind, label: "Smell" },
    kinesthetic: { icon: Sparkles, label: "Kinesthetic" },
};

// --- Helper Components ---

function RealityMeter({ value }: { value?: string }) {
    if (!value) return null;
    const level = REALITY_LEVELS.find((l) => l.value === value) || REALITY_LEVELS[1];
    const percentage = level.position;

    return (
        <div className="space-y-1.5">
            <div className="flex items-center justify-between text-[10px] text-slate-400">
                <span>Less Real</span>
                <span>Most Real</span>
            </div>
            <div className="relative h-2 bg-slate-100 rounded-full overflow-hidden">
                <div
                    className={cn("absolute inset-y-0 left-0 rounded-full transition-all duration-500", level.color)}
                    style={{ width: `${Math.max(percentage, 8)}%` }}
                />
            </div>
            <p className="text-xs font-medium text-slate-700 text-center">{level.label}</p>
        </div>
    );
}

function VividnessBar({ value }: { value?: string }) {
    if (!value) return null;
    const levelIdx = VIVIDNESS_LEVELS.findIndex((l) => l.value === value);
    const level = VIVIDNESS_LEVELS[levelIdx >= 0 ? levelIdx : 1];
    const percentage = ((levelIdx >= 0 ? levelIdx : 1) + 1) / VIVIDNESS_LEVELS.length * 100;

    return (
        <div className="space-y-1.5">
            <div className="flex items-center justify-between text-[10px] text-slate-400">
                <span>Faint</span>
                <span>Hyper-Vivid</span>
            </div>
            <div className="relative h-2 bg-slate-100 rounded-full overflow-hidden">
                <div
                    className={cn("absolute inset-y-0 left-0 rounded-full transition-all duration-500", level.color)}
                    style={{ width: `${Math.max(percentage, 8)}%` }}
                />
            </div>
            <p className="text-xs font-medium text-slate-700 text-center">{level.label}</p>
        </div>
    );
}

// --- Main Component ---

interface PhenomenologyCardProps {
    phenomenology: PhenomenologyData | null | undefined;
    className?: string;
}

export function PhenomenologyCard({ phenomenology, className }: PhenomenologyCardProps) {
    if (!phenomenology) return null;

    const { reality_comparison, vividness, sensory_modalities, emotional_progression, altered_cognition } = phenomenology;

    // Don't render if all fields are empty
    const hasContent = reality_comparison || vividness
        || (sensory_modalities && sensory_modalities.length > 0)
        || (emotional_progression && emotional_progression.length > 0)
        || (altered_cognition && altered_cognition.length > 0);

    if (!hasContent) return null;

    return (
        <div className={cn("space-y-4", className)}>
            {/* Reality + Vividness meters */}
            {(reality_comparison || vividness) && (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {reality_comparison && (
                        <div className="bg-slate-50 rounded-xl p-3 border border-slate-100">
                            <h4 className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider mb-2">
                                Reality Comparison
                            </h4>
                            <RealityMeter value={reality_comparison} />
                        </div>
                    )}
                    {vividness && (
                        <div className="bg-slate-50 rounded-xl p-3 border border-slate-100">
                            <h4 className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider mb-2">
                                Vividness
                            </h4>
                            <VividnessBar value={vividness} />
                        </div>
                    )}
                </div>
            )}

            {/* Sensory Modalities */}
            {sensory_modalities && sensory_modalities.length > 0 && (
                <div>
                    <h4 className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider mb-2">
                        Sensory Channels
                    </h4>
                    <div className="flex flex-wrap gap-2">
                        {sensory_modalities.map((modality) => {
                            const config = SENSORY_ICONS[modality.toLowerCase()];
                            const Icon = config?.icon || Sparkles;
                            const label = config?.label || modality.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());

                            return (
                                <div
                                    key={modality}
                                    className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg bg-violet-50 border border-violet-200 text-violet-700"
                                >
                                    <Icon className="w-3.5 h-3.5" />
                                    <span className="text-xs font-medium">{label}</span>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Emotional Progression */}
            {emotional_progression && emotional_progression.length > 0 && (
                <div>
                    <h4 className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider mb-2">
                        Emotional Progression
                    </h4>
                    <div className="flex flex-wrap items-center gap-1">
                        {emotional_progression.map((emotion, idx) => (
                            <span key={idx} className="flex items-center gap-1">
                                <span className="inline-flex items-center px-2 py-0.5 rounded-md bg-rose-50 border border-rose-200 text-rose-700 text-[11px] font-medium">
                                    {emotion.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase())}
                                </span>
                                {idx < emotional_progression.length - 1 && (
                                    <ArrowRight className="w-3 h-3 text-slate-300" />
                                )}
                            </span>
                        ))}
                    </div>
                </div>
            )}

            {/* Altered Cognition */}
            {altered_cognition && altered_cognition.length > 0 && (
                <div>
                    <h4 className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider mb-2">
                        Altered Cognition
                    </h4>
                    <div className="flex flex-wrap gap-1.5">
                        {altered_cognition.map((item) => (
                            <span
                                key={item}
                                className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-amber-50 border border-amber-200 text-amber-700 text-[11px] font-medium"
                            >
                                <Brain className="w-3 h-3" />
                                {item.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase())}
                            </span>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}
